<script>
document.addEventListener('DOMContentLoaded',()=>{const form=document.querySelector('[data-stock-case-form]');if(!form)return;const task=form.querySelector('[data-case-kind]'),carton=form.querySelector('[data-case-carton]'),releases=form.querySelector('[data-case-release]');const update=()=>{form.querySelectorAll('[data-case-section]').forEach(section=>{const active=section.dataset.caseSection.split(' ').includes(task.value);section.hidden=!active;section.querySelectorAll('input,select,textarea').forEach(input=>input.disabled=!active);});};const fill=()=>{releases.replaceChildren();const parts=JSON.parse(carton.selectedOptions[0]?.dataset.contents??'[]');parts.forEach(part=>{const label=document.createElement('label');label.className='field';const span=document.createElement('span');span.textContent=`Unpack from ${part.batch_code} (original ${part.quantity})`;const input=document.createElement('input');input.type='number';input.name=`release[${part.batch_id}]`;input.min='0';input.max=part.quantity;input.step='0.001';input.value='0';label.append(span,input);releases.append(label);});update();};task.addEventListener('change',update);carton.addEventListener('change',fill);fill();});
</script>
